/* AP Physics 1 Course and Exam Description (effective Fall 2024), Unit 4: Linear Momentum, topics 4.1-4.4.
   https://apcentral.collegeboard.org/courses/ap-physics-1
   Original wording. Every cart, skater, ball, sensor and dart is fictional and every number is invented. Near Earth g = 9.8 m/s²;
   collisions happen on smooth, level tracks (no external horizontal force) unless a prompt says otherwise. Right is positive and
   velocities are signed. Collision diagrams draw each arrow at one scale (0.26 grid units per m/s); force-time graphs are drawn
   from the stated points. Pictures are drawn by code from the same numbers the questions use. */
const OBJ=['cart','puck','trolley','sled','railcar','bumper car','skater','wagon'];
const r4=x=>Math.round(x*1e4)/1e4+0,sg=x=>x<0?`−${-x}`:`${x}`,dirOf=v=>v<0?'left':'right',ok2=x=>Math.abs(x*100-Math.round(x*100))<1e-7;
const DP=' Give your answer to two decimal places.',rd=x=>Number.isInteger(x)?'':DP;
const cap=s=>s[0].toUpperCase()+s.slice(1);
const tab=(title,rows)=>({t:'setups',title,head:'Quantity',rows,cols:['Value']});
const board=(title,lines)=>({t:'board',title,lines,box:true});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
/* Before/after diagram: rows of {tag, things:[{n,m,v,x,w}], wall}; v = null draws "v = ?", 0 draws "v = 0" */
function diag(title,rows,sc=0.26){const q={t:'figure',title,view:[0,16,-2.9,2.9],pts:{},hide:'',dots:'',segs:[],polys:[],notes:[]};let n=0;
 const P=(x,y)=>{const k=`Q${n++}`;q.pts[k]=[x,y];return k;};
 rows.forEach((row,ri)=>{const y=rows.length===1?0.1:ri===0?1.2:-1.6;q.notes.push({at:[1.3,y],text:row.tag});
  if(row.wall){const a=P(14.6,y-0.9),b=P(15.2,y-0.9),c=P(15.2,y+0.9),d=P(14.6,y+0.9);q.polys.push({v:a+b+c+d,col:4});}
  row.things.forEach((t,i)=>{const w=t.w??2.6,x=t.x,h=0.5,col=t.col??i,a=P(x-w/2,y-h),b=P(x+w/2,y-h),c=P(x+w/2,y+h),d=P(x-w/2,y+h);q.polys.push({v:a+b+c+d,col});
   q.notes.push({at:[x,y],text:`${t.n} ${t.m} kg`,col});const ya=y+0.85;
   if(t.v==null)q.notes.push({at:[x,ya+0.45],text:'v = ?',col});
   else if(t.v===0)q.notes.push({at:[x,ya+0.45],text:'v = 0',col});
   else{const x1=x+t.v*sc,dir=Math.sign(t.v),s=P(x,ya),e=P(x1,ya),h1=P(x1-dir*0.25,ya+0.14),h2=P(x1-dir*0.25,ya-0.14);q.segs.push({v:s+e,col});q.polys.push({v:e+h1+h2,col});q.notes.push({at:[x,ya+0.45],text:`v = ${t.v>0?'+':'−'}${Math.abs(t.v)} m/s`,col});}});});
 q.hide=Object.keys(q.pts).join(' ');return q;}
const XA=5.5,XB=11.5;
/* one before row and one after row for two carts; after = [vA,vB] or a single common velocity when stuck */
function collide(title,A,B,after,names=['A','B']){const [a,b]=[{n:names[0],m:A[0],v:A[1],x:XA},{n:names[1],m:B[0],v:B[1],x:XB}];
 const post=Array.isArray(after)?[{...a,v:after[0]},{...b,v:after[1]}]:[{n:`${a.n}+${b.n}`,m:A[0]+B[0],v:after,x:8.5,w:5.4,col:2}];
 return diag(title,[{tag:'Before',things:[a,b]},{tag:'After',things:post}]);}
const ft=(P,title='Fictional force sensor: horizontal t (s), vertical F (N)')=>{const ts=P.map(p=>p[0]),fs=P.map(p=>p[1]),lo=Math.min(0,...fs),hi=Math.max(0,...fs),pad=(hi-lo)*0.18;
 return {t:'plot',title,x:[0,Math.ceil(Math.max(...ts))],y:[lo<0?Math.floor(lo-pad):0,Math.ceil(hi+pad)],paths:[{pts:P}],areas:[{pts:[[P[0][0],0],...P,[P.at(-1)[0],0]]}]};};
const area=P=>{let s=0;for(let i=1;i<P.length;i++)s+=(P[i][1]+P[i-1][1])/2*(P[i][0]-P[i-1][0]);return s;};
const ptsText=P=>P.map(([t,f])=>`(${sg(t)}, ${sg(f)})`).join(', ');
const TRY={imp:'Try it: a constant 18 N net force acts along the motion of a fictional 6 kg cart that starts at rest, for 5 s. What is its speed afterwards, in m/s?',
 area:'Try it: a fictional force sensor shows straight lines through (0, 0), (2, 14), (6, 14), (8, 0) (t in s, F in N) for a 12 kg cart that starts at rest. What is its speed at 8 s, in m/s?',
 cons:'Try it: on a smooth track a fictional 5 kg cart moves right at 6 m/s and a fictional 3 kg cart moves left at 4 m/s. They collide and stick. Taking right as positive, what is their velocity afterwards, in m/s?',
 elastic:'Try it: a fictional 2 kg puck moving right at 9 m/s hits a fictional 4 kg puck at rest, head-on and elastically. Taking right as positive, what is the 2 kg puck’s velocity just afterwards, in m/s?'};
/* the plot of velocity-ratio curves for an elastic hit on a target at rest, r = m2/m1 */
const RATIO=(()=>{const pts1=[],pts2=[];for(let i=0;i<=20;i++){const r=i/4;pts1.push([r,Math.round((1-r)/(1+r)*1e4)/1e4]);pts2.push([r,Math.round(2/(1+r)*1e4)/1e4]);}
 return {t:'plot',title:'Elastic hit on a target at rest: horizontal m₂/m₁, vertical v′/v₁',x:[0,5],y:[-1,2],paths:[{pts:pts1,label:'A: v₁′/v₁'},{pts:pts2,label:'B: v₂′/v₁'}],points:[{x:1,y:0,label:'equal masses: A stops'}]};})();
/* a ballistic pendulum: cords of 2.5 m, block raised 0.1 m */
const PENDULUM=(()=>{const L=2.5,h=0.1,th=Math.acos((L-h)/L),bx=L*Math.sin(th),by=L-L*Math.cos(th);
 return {t:'figure',title:'Fictional dart and block: swing up h = 0.1 m',view:[-1.6,3.2,-0.8,3.2],pts:{P:[0,L],R:[0,0],S:[bx,by],H:[-0.9,by],G:[-0.9,0]},hide:'PRSHG',dots:'P',
  segs:[{v:'PR',col:2},{v:'PS',col:2,dash:true},{v:'HS',dash:true,col:4},{v:'HG',col:0}],notes:[{at:[0,-0.45],text:'rest: block + dart 0.9 kg'},{at:[bx+0.5,by+0.45],text:'highest point'},{at:[-1.25,by/2+0.3],text:'h = 0.1 m'},{at:[0,L+0.35],text:'light cords, 2.5 m'}]};})();
const ENERGY={t:'chart',kind:'bars',title:'Fictional 2 kg carts: kinetic energy (J), 2 kg cart at 6 m/s hits 2 kg cart at rest',bars:[{label:'before',value:36},{label:'elastic',value:36},{label:'partly inelastic',value:22.5},{label:'stick',value:18}],suffix:' J'};
const CMPLOT={t:'plot',title:'Fictional carts: horizontal t (s), vertical x (m)',x:[0,6],y:[0,20],paths:[{pts:[[0,0],[2,12]],label:'A'},{pts:[[0,12],[2,12]],label:'B'},{pts:[[2,12],[6,18]],label:'A+B'},{pts:[[0,9],[6,18]],label:'CM',dash:true}]};
const STOP={t:'plot',title:'Fictional dummy, same impulse 900 N·s: horizontal t (s), vertical F (N)',x:[0,0.25],y:[0,20000],paths:[{pts:[[0,18000],[0.05,18000]],label:'dash'},{pts:[[0,4500],[0.2,4500]],label:'air bag'}],areas:[{pts:[[0,0],[0.05,0],[0.05,18000],[0,18000]],col:0},{pts:[[0,0],[0.2,0],[0.2,4500],[0,4500]],col:1}]};
const SUMMARY=board('Choose the law, then check signs',['Impulse: J = FΔt = Δp','Graph: J = area under F against t','Isolated system: Σp before = Σp after','Elastic: KE kept; stick: one velocity']);
const STEPS=[
 {skill:'mom',say:'Linear momentum is the vector p = mv, in kg·m/s. It points the way the object moves, so choose a positive direction first and let velocity carry the sign. Take right as positive: a fictional 2.5 kg cart gliding left at 4.8 m/s has v = −4.8 m/s and p = −12 kg·m/s. Doubling the mass or the speed doubles the momentum. Momentum is zero only when the velocity is zero, and it changes when the velocity changes in size or in direction.',eq:'p = mv = 2.5 × (−4.8) = −12 kg·m/s',pic:diag('Fictional cart: momentum has a direction',[{tag:'Now',things:[{n:'cart',m:2.5,v:-4.8,x:8.5}]}])},
 {skill:'mom',say:'The momentum of a system is the vector sum of the momenta of its parts, with signs. Fictional cart A, 3 kg at +5 m/s, has +15 kg·m/s. Fictional cart B, 4.5 kg at −2 m/s, has −9 kg·m/s. The total is +6 kg·m/s even though B is the heavier cart, because opposite directions subtract. To rank momenta compare m × |v|, never the masses or the speeds alone.',eq:'p_total = 3 × 5 + 4.5 × (−2) = 15 − 9 = +6 kg·m/s',pic:diag('Fictional carts: total momentum +6 kg·m/s',[{tag:'Now',things:[{n:'A',m:3,v:5,x:XA},{n:'B',m:4.5,v:-2,x:XB}]}])},
 {skill:'imp',say:'Impulse is the net force times the time it acts, J = F_net Δt, in N·s (the same unit as kg·m/s). The impulse–momentum theorem says J = Δp = mΔv. A fictional 7 kg cart at rest feels a constant 14 N net force for 2.5 s. The impulse is 35 N·s, so its velocity changes by 35 ÷ 7 = 5 m/s. The impulse points along the net force, so a force opposite the motion gives a negative impulse and slows the cart.',eq:'J = FΔt = 14 × 2.5 = 35 N·s = Δp; Δv = 35 ÷ 7 = 5 m/s',pic:{t:'plot',title:'Fictional constant force: horizontal t (s), vertical F (N)',x:[0,3],y:[0,20],paths:[{pts:[[0,14],[2.5,14]],label:'14 N'}],areas:[{pts:[[0,0],[2.5,0],[2.5,14],[0,14]],col:0}]},
  check:{prompt:TRY.imp,answer:15,options:[15,90,3],hint:'Impulse is 18 × 5 = 90 N·s. Divide by the 6 kg mass to get the change in speed.',pic:tab('Fictional cart',[['mass','6 kg, at rest'],['net force','18 N, along the motion'],['time','5 s']])}},
 {skill:'imp',say:'Impulse is a vector, so a bounce counts the reversal. A fictional 0.35 kg ball hits a wall at +8 m/s and rebounds at −5 m/s. Its momentum goes from +2.8 to −1.75 kg·m/s, so the impulse the wall gives it is −1.75 − 2.8 = −4.55 N·s. If the contact lasts 0.025 s the average force on the ball is −182 N, toward the left. The rebound makes the impulse bigger than if the ball had simply stopped, which would be −2.8 N·s.',eq:'J = m(v_f − v_i) = 0.35 × (−5 − 8) = −4.55 N·s; F_avg = −4.55 ÷ 0.025 = −182 N',pic:diag('Fictional ball and wall: the velocity reverses',[{tag:'Before',things:[{n:'ball',m:0.35,v:8,x:10.5}],wall:true},{tag:'After',things:[{n:'ball',m:0.35,v:-5,x:10.5}],wall:true}])},
 {skill:'imp',say:'For a given change in momentum, a longer contact time means a smaller average force, F_avg = Δp ÷ Δt. A fictional 60 kg crash-test dummy slows from 15 m/s to rest, a momentum change of 900 kg·m/s in size. Stopped by a rigid dash in 0.05 s the average force is 18 000 N. Stopped by an air bag in 0.2 s it is 4 500 N. The two rectangles have the same area, the same impulse; the air bag only spreads it over more time.',eq:'F_avg = Δp ÷ Δt: 900 ÷ 0.05 = 18 000 N; 900 ÷ 0.2 = 4 500 N',pic:STOP},
 {skill:'area',say:'When the force changes, the impulse is the area between the force–time graph and the time axis. Split the shape into triangles and rectangles. A fictional force sensor draws straight lines through (0, 0), (1.5, 18), (4.5, 18) and (6, 0), with t in seconds and F in newtons. The two triangles each give 13.5 N·s and the rectangle gives 54 N·s, so J = 81 N·s. For a 9 kg cart starting at rest that is a speed of 9 m/s, and the average force is 81 ÷ 6 = 13.5 N.',eq:'J = ½(1.5)(18) + (3)(18) + ½(1.5)(18) = 81 N·s; v = 81 ÷ 9 = 9 m/s',pic:ft([[0,0],[1.5,18],[4.5,18],[6,0]])},
 {skill:'area',say:'Area below the time axis counts as negative impulse. A fictional sensor reads straight lines through (0, 0), (3, 10), (6, 0), (8, −9) and (10, 0). The push above the axis gives +30 N·s and the pull below it gives −18 N·s, so the net impulse is +12 N·s. A 4 kg cart moving at +2 m/s ends at 2 + 12 ÷ 4 = 5 m/s. Add the areas with their signs; do not add their sizes.',eq:'J = ½(6)(10) − ½(4)(9) = 30 − 18 = +12 N·s; v = 2 + 12 ÷ 4 = 5 m/s',pic:ft([[0,0],[3,10],[6,0],[8,-9],[10,0]]),
  check:{prompt:TRY.area,answer:7,options:[7,14,84],hint:'Add the trapezoid: two triangles of 14 N·s and a rectangle of 56 N·s, then divide by the 12 kg mass.',pic:ft([[0,0],[2,14],[6,14],[8,0]])}},
 {skill:'cons',say:'A system’s momentum changes only through external impulse: J_ext = Δp_system. Forces between objects inside the system are equal and opposite, so their impulses cancel. If the net external force is zero, or its impulse is negligible during a brief interaction, total momentum is conserved: Σp before = Σp after. A fictional 60 kg skater at rest throws a 2 kg ball forward at +12 m/s. With right positive, 0 = 60v + 2 × 12, so the skater recoils at −0.4 m/s.',eq:'0 = 60v + 2 × 12; v = −24 ÷ 60 = −0.4 m/s',pic:diag('Fictional skater and ball: recoil from rest',[{tag:'Before',things:[{n:'skater+ball',m:62,v:0,x:8.5,w:5.4}]},{tag:'After',things:[{n:'skater',m:60,v:-0.4,x:XA},{n:'ball',m:2,v:12,x:XB}]}])},
 {skill:'cons',say:'In a perfectly inelastic collision the objects leave with one common velocity: m₁v₁ + m₂v₂ = (m₁ + m₂)v. Take right as positive. A fictional 6 kg cart at +7 m/s hits a 4 kg cart at −3 m/s and they stick. The total momentum is 42 − 12 = +30 kg·m/s and the total mass is 10 kg, so v = +3 m/s. Forgetting the minus sign on the left-moving cart would give 5.4 m/s, which is wrong. If the two momenta cancel exactly, the carts stop.',eq:'6 × 7 + 4 × (−3) = (6 + 4)v; v = 30 ÷ 10 = +3 m/s',pic:collide('Fictional carts stick together',[6,7],[4,-3],3),
  check:{prompt:TRY.cons,answer:2.25,options:[2.25,5.25,18],hint:'Left-moving momentum is negative: 5 × 6 − 3 × 4 = 18 kg·m/s. Divide by the total mass 8 kg.',pic:collide('Fictional carts stick together',[5,6],[3,-4],null)}},
 {skill:'cons',say:'Internal forces change how momentum is shared, not how much there is. A fictional 8 kg cart rolls right at +3 m/s and an internal spring splits it into a 5 kg piece and a 3 kg piece. The 5 kg piece moves at +6 m/s. The total before is 24 kg·m/s, so 24 = 5 × 6 + 3v and v = −2 m/s: the 3 kg piece moves left. Check the sum: 30 − 6 = 24 kg·m/s.',eq:'8 × 3 = 5 × 6 + 3v; v = (24 − 30) ÷ 3 = −2 m/s',pic:diag('Fictional cart splits into two pieces',[{tag:'Before',things:[{n:'cart',m:8,v:3,x:8.5,w:5.4}]},{tag:'After',things:[{n:'piece',m:5,v:6,x:XA},{n:'piece',m:3,v:-2,x:XB}]}])},
 {skill:'cm',say:'The center of mass moves with v_cm = Σ(mv) ÷ Σm = p_total ÷ m_total. With no net external force it moves at constant velocity, even straight through a collision. Fictional cart A (2 kg, +6 m/s, starting at x = 0) heads for cart B (6 kg, at rest at x = 12 m). Then v_cm = 12 ÷ 8 = 1.5 m/s and x_cm = 72 ÷ 8 = 9 m at t = 0. They meet at t = 2 s at x = 12 m and stick; the joined carts move at 1.5 m/s along the same center-of-mass line.',eq:'v_cm = (2 × 6 + 6 × 0) ÷ 8 = 1.5 m/s; x_cm = 9 + 1.5t',pic:CMPLOT},
 {skill:'ke',say:'Compare the total kinetic energy, KE = ½mv², before and after. In an elastic collision it is unchanged. In an inelastic collision some becomes thermal energy, sound or deformation. In a perfectly inelastic collision the objects leave with one velocity, which loses the most. Momentum is conserved in all three when the system is isolated. A fictional 2 kg cart at 6 m/s (36 J) hits a 2 kg cart at rest: elastic leaves 36 J, a partial bounce 22.5 J, sticking 18 J. An ordinary collision does not add kinetic energy.',eq:'KE = ½mv²: 36 J → 36 J (elastic), 22.5 J (inelastic), 18 J (stick)',pic:ENERGY},
 {skill:'elastic',say:'In a head-on elastic collision both momentum and kinetic energy are conserved, which means the relative speed of approach equals the relative speed of separation: v₁ − v₂ = −(v₁′ − v₂′). Solve that with the momentum equation. Fictional A (3 kg, +8 m/s) hits B (1 kg, −4 m/s). Momentum: 24 − 4 = 20. Approach speed 12 m/s, so v₂′ = v₁′ + 12 and 3v₁′ + v₁′ + 12 = 20, giving v₁′ = +2 m/s and v₂′ = +14 m/s. Check kinetic energy: 96 + 8 = 6 + 98 = 104 J.',eq:'3v₁′ + 1(v₁′ + 12) = 20; v₁′ = 2 m/s; v₂′ = 14 m/s',pic:collide('Fictional elastic collision',[3,8],[1,-4],[2,14])},
 {skill:'elastic',say:'For a target at rest, the elastic results are v₁′ = (m₁ − m₂) ÷ (m₁ + m₂) × v₁ and v₂′ = 2m₁ ÷ (m₁ + m₂) × v₁. Equal masses: A stops and B leaves with A’s velocity. A heavy cart hitting a light one keeps going forward while the light one shoots ahead faster. A light cart hitting a heavy one bounces back and the heavy one barely moves. A fictional 5 kg cart at +6 m/s hits a 1 kg cart at rest: v₁′ = 4 m/s and v₂′ = 10 m/s.',eq:'v₁′ = (5 − 1) ÷ 6 × 6 = 4 m/s; v₂′ = 2 × 5 ÷ 6 × 6 = 10 m/s',pic:RATIO,
  check:{prompt:TRY.elastic,answer:-3,options:[-3,3,6],hint:'Use v₁′ = (m₁ − m₂) ÷ (m₁ + m₂) × v₁ with the lighter puck as 1. The sign shows which way it moves.',pic:collide('Fictional elastic collision',[2,9],[4,0],null)}},
 {skill:'ke',say:'A ballistic pendulum uses both ideas in two stages. In the brief collision, momentum is conserved and kinetic energy is lost: mv = (m + M)V. In the swing, mechanical energy is conserved: ½(m + M)V² = (m + M)gh. A fictional 0.06 kg dart sticks in a 0.84 kg block and they rise 0.1 m (g = 9.8 m/s²). So V = 1.4 m/s and the dart’s speed was 0.9 × 1.4 ÷ 0.06 = 21 m/s. Kinetic energy falls from 13.23 J to 0.882 J, a loss of 12.348 J, about 93.3 percent.',eq:'V = √(2 × 9.8 × 0.1) = 1.4 m/s; v = (0.9 ÷ 0.06) × 1.4 = 21 m/s',pic:PENDULUM},
 {skill:'mom',summary:true,say:'Pick the tool from the question. Momentum p = mv is signed. An impulse J = FΔt, or the area under a force–time graph, equals the change in momentum of one object. If the objects form an isolated system, total momentum is the same before and after, and the center of mass keeps its velocity. Then compare kinetic energy: unchanged for elastic, lower for inelastic, lowest for sticking. Keep signs and units on every line.',eq:'J = Δp; Σp conserved when J_ext ≈ 0; compare KE',pic:SUMMARY}
];
