 const put=(skill,prompt,answer,pic,why,accept)=>{if(typeof answer==='number'&&!ok2(answer))return;if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,why,accept);};
 const fact=(skill,rows)=>rows.forEach(([stem,right,w1,w2,why],i)=>{const c=choose(right,[w1,w2],i);put(skill,`${stem} ${c.text}. Answer A, B or C.`,c.letter,scenario('Reason from the physics',stem),why,[right]);});
 let k=0;const O=()=>OBJ[k++%OBJ.length],A=r4;
